package com.volna.profile_service.security;import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.util.UUID;@Component public class JwtTokenProvider{private final SecretKey key;public JwtTokenProvider(@Value("${app.jwt.secret}")String s){key=Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));}public Claims claims(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload();}public boolean valid(String t){try{claims(t);return true;}catch(Exception e){return false;}}public UUID userId(String t){return UUID.fromString(claims(t).getSubject());}}
